class Solution:

    def maxProduct(self, s):
        ans = 0

        def isPalindrome(s):
            i = 0
            j = len(s) - 1
            while i < j:
                if s[i] != s[j]:
                    return bool(False)
                i += 1
                j -= 1
            return bool(True)

        @functools.lru_cache(None)
        def dfs(i, s1, s2):
            nonlocal ans
            if i == len(s):
                if isPalindrome(s1) and isPalindrome(s2):
                    ans = max(ans, len(s1) * len(s2))
                return
            dfs(i + 1, s1 + s[i], s2)
            dfs(i + 1, s1, s2 + s[i])
            dfs(i + 1, s1, s2)
        dfs(0, '', '')
        return ans

