class FenwichTree:

    def __init__(self, n):
        self.n = n
        self.sums = [0] * (2 * n + 1)

    def add(self, i, delta):
        i += self.n + 1
        while i < len(self.sums):
            self.sums[i] += delta
            i += i & -i

    def get(self, i):
        i += self.n + 1
        summ = 0
        while i > 0:
            summ += self.sums[i]
            i -= i & -i
        return summ

class Solution:

    def subarraysWithMoreZerosThanOnes(self, nums):
        MOD = 1000000007
        ans = 0
        prefix = 0
        tree = FenwichTree(len(nums))
        tree.add(0, 1)
        for num in nums:
            prefix += -1 if num == 0 else 1
            ans += tree.get(prefix - 1)
            ans %= MOD
            tree.add(prefix, 1)
        return ans

