class Solution:

    def maximumAlternatingSubarraySum(self, nums):
        ans = -math.inf
        even = 0
        odd = 0
        for i in range(len(nums)):
            if i % 2 == 0:
                even += nums[i]
            else:
                even = max(0, even - nums[i])
            ans = max(ans, even)
