class Solution:

    def networkBecomesIdle(self, edges, patience):
        n = len(patience)
        ans = 0
        graph = [[] for _ in range(n)]
        q = collections.deque([0])
        dist = [math.inf] * n
        dist[0] = 0
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        while q:
            for _ in range(len(q)):
                u = q.popleft()
                for v in graph[u]:
                    if dist[v] == math.inf:
                        dist[v] = dist[u] + 1
                        q.append(v)
        for i in range(1, n):
            numResending = (dist[i] * 2 - 1) // patience[i]
            lastResendingTime = patience[i] * numResending
            lastArrivingTime = lastResendingTime + dist[i] * 2
            ans = max(ans, lastArrivingTime)
        return ans + 1

class Solution:

    def kthSmallestProduct(self, nums1, nums2, k):
        A1 = [-num for num in nums1 if num < 0][::-1]
        A2 = [num for num in nums1 if num >= 0]
        B1 = [-num for num in nums2 if num < 0][::-1]
        B2 = [num for num in nums2 if num >= 0]
        negCount = len(A1) * len(B2) + len(A2) * len(B1)
        if k > negCount:
            k -= negCount
            sign = 1
        else:
            k = negCount - k + 1
            sign = -1
            B1, B2 = (B2, B1)

        def numProductNoGreaterThan(A, B, m):
            ans = 0
            j = len(B) - 1
            for i in range(len(A)):
                while j >= 0 and A[i] * B[j] > m:
                    j -= 1
                ans += j + 1
            return ans
        l = 0
        r = 10 ** 10
        while l < r:
            m = (l + r) // 2
            if numProductNoGreaterThan(A1, B1, m) + numProductNoGreaterThan(A2, B2, m) >= k:
                r = m
            else:
                l = m + 1
        return sign * l

import pandas as pd

def accepted_candidates(candidates, rounds):
    merged_df = pd.merge(candidates, rounds, on='interview_id')
    filtered_df = merged_df[merged_df['years_of_exp'] >= 2]
    grouped_df = filtered_df.groupby('candidate_id').agg({'score': 'sum'})
    return grouped_df[grouped_df['score'] > 15].reset_index()[['candidate_id']]

class Solution:
    def run(self, tables):
        candidates = pd.DataFrame(list(tables.values())[0])
        rounds = pd.DataFrame(list(tables.values())[1])
        result = accepted_candidates(candidates, rounds)
        if isinstance(result, pd.DataFrame):
            if result.index.name is not None:
                result = result.reset_index()
            return result.astype(object).where(pd.notnull(result), None).to_dict(orient="records")
        return result

