class Solution:

    def countValidWords(self, sentence):

        def isValid(token):
            countHyphen = 0
            for i, c in enumerate(token):
                if c.isdigit():
                    return bool(False)
                if c == '-':
                    if i == 0 or not token[i - 1].isalpha():
                        return bool(False)
                    if i == len(token) - 1 or not token[i + 1].isalpha():
                        return bool(False)
                    if countHyphen == 1:
                        return bool(False)
                    countHyphen += 1
                if c in ['!', '.', ',']:
                    if i != len(token) - 1:
                        return bool(False)
            return bool(True)
        return sum((isValid(token) for token in sentence.split()))

class Solution:

    def nextBeautifulNumber(self, n):

        def isBalance(num):
            count = [0] * 10
            while num > 0:
                if num % 10 == 0:
                    return bool(False)
                count[num % 10] += 1
                num //= 10
            return bool(all((c == i for i, c in enumerate(count) if c)))
        n += 1
        while not isBalance(n):
            n += 1
        return n

class Solution:

    def minimumCost(self, sentence, k):
        if len(sentence) <= k:
            return 0
        words = sentence.split()
        dp = [0] * (len(words) + 1)
        for i in range(1, len(words) + 1):
            n = len(words[i - 1])
            dp[i] = dp[i - 1] + (k - n) ** 2
            for j in range(i - 1, 0, -1):
                n += len(words[j - 1]) + 1
                if n > k:
                    break
                dp[i] = min(dp[i], dp[j - 1] + (k - n) ** 2)
        lastRowLen = len(words[-1])
        i = len(words) - 2
        while i > 0 and lastRowLen + len(words[i]) + 1 <= k:
            lastRowLen += len(words[i]) + 1
            i -= 1
        return min(dp[i + 1:len(words)])

