class Solution:

    def possiblyEquals(self, s1, s2):

        def getNums(s):
            nums = {int(s)}
            for i in range(1, len(s)):
                nums |= {x + y for x in getNums(s[:i]) for y in getNums(s[i:])}
            return nums

        def getNextLetterIndex(s, i):
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            return j

        @functools.lru_cache(None)
        def dp(i, j, paddingDiff):
            """
      Returns True if s1[i..n) matches s2[j..n), accounting for the padding
      difference. Here, `paddingDiff` represents the signed padding. A positive
      `paddingDiff` indicates that s1 has an additional number of offset bytes
      compared to s2.
      """
            if i == len(s1) and j == len(s2):
                return bool(paddingDiff == 0)
            if i < len(s1) and s1[i].isdigit():
                nextLetterIndex = getNextLetterIndex(s1, i)
                for num in getNums(s1[i:nextLetterIndex]):
                    if dp(nextLetterIndex, j, paddingDiff + num):
                        return bool(True)
            elif j < len(s2) and s2[j].isdigit():
                nextLetterIndex = getNextLetterIndex(s2, j)
                for num in getNums(s2[j:nextLetterIndex]):
                    if dp(i, nextLetterIndex, paddingDiff - num):
                        return bool(True)
            elif paddingDiff > 0:
                if j < len(s2):
                    return bool(dp(i, j + 1, paddingDiff - 1))
            elif paddingDiff < 0:
                if i < len(s1):
                    return bool(dp(i + 1, j, paddingDiff + 1))
            elif i < len(s1) and j < len(s2) and (s1[i] == s2[j]):
                return bool(dp(i + 1, j + 1, 0))
            return bool(False)
        return bool(dp(0, 0, 0))

class Solution:

    def numberOfCleanRooms(self, room):
        DIRS = ((0, 1), (1, 0), (0, -1), (-1, 0))
        m = len(room)
        n = len(room[0])
        ans = 1
        i = 0
        j = 0
        state = 0
        seen = {(i, j, state)}
        room[i][j] = 2
        while True:
            x = i + DIRS[state][0]
            y = j + DIRS[state][1]
            if x < 0 or x == m or y < 0 or (y == n) or (room[x][y] == 1):
                state = (state + 1) % 4
            else:
                if room[x][y] == 0:
                    ans += 1
                    room[x][y] = 2
                i = x
                j = y
            if (x, y, state) in seen:
                return ans
            seen.add((x, y, state))

class Solution:

    def countVowelSubstrings(self, word):
        VOWELS = 'aeiou'

        def countVowelSubstringsAtMost(goal):
            ans = 0
            k = goal
            count = collections.Counter()
            l = 0
            for r, c in enumerate(word):
                if c not in VOWELS:
                    l = r + 1
                    k = goal
                    count = collections.Counter()
                    continue
                count[c] += 1
                if count[c] == 1:
                    k -= 1
                while k == -1:
                    count[word[l]] -= 1
                    if count[word[l]] == 0:
                        k += 1
                    l += 1
                ans += r - l + 1
            return ans
        return countVowelSubstringsAtMost(5) - countVowelSubstringsAtMost(4)

