class Solution:

    def minimizedMaximum(self, n, quantities):
        l = 1
        r = max(quantities)

        def numStores(m):
            return sum(((q - 1) // m + 1 for q in quantities))
        while l < r:
            m = (l + r) // 2
            if numStores(m) <= n:
                r = m
            else:
                l = m + 1
        return l

class Solution:

    def equalCountSubstrings(self, s, count):
        maxUnique = len(set(s))
        ans = 0
        for unique in range(1, maxUnique + 1):
            windowSize = unique * count
            lettersCount = collections.Counter()
            uniqueCount = 0
            for i, c in enumerate(s):
                lettersCount[c] += 1
                if lettersCount[c] == count:
                    uniqueCount += 1
                if i >= windowSize:
                    lettersCount[s[i - windowSize]] -= 1
                    if lettersCount[s[i - windowSize]] == count - 1:
                        uniqueCount -= 1
                ans += uniqueCount == unique
        return ans

