            pv = uf.find(v)
            isValid = True
            if pu != pv:
                for x, y in restrictions:
                    px = uf.find(x)
                    py = uf.find(y)
                    if (pu, pv) in [(px, py), (py, px)]:
                        isValid = False
                        break
            ans.append(isValid)
            if isValid:
                uf.unionByRank(pu, pv)
        return ans

