class Solution:

    def validArrangement(self, pairs):
        ans = []
        graph = collections.defaultdict(list)
        outDegree = collections.Counter()
        inDegrees = collections.Counter()
        for start, end in pairs:
            graph[start].append(end)
            outDegree[start] += 1
            inDegrees[end] += 1

        def getStartNode():
            for u in graph.keys():
                if outDegree[u] - inDegrees[u] == 1:
                    return u
            return pairs[0][0]

        def euler(u):
            stack = graph[u]
            while stack:
                v = stack.pop()
                euler(v)
                ans.append([u, v])
        euler(getStartNode())
        return ans[::-1]

