            if count[candy] == 0:
                del count[candy]
                unique -= 1
            if i >= k:
                count[candies[i - k]] += 1
                if count[candies[i - k]] == 1:
                    unique += 1
            if i >= k - 1:
                ans = max(ans, unique)
        return ans

