    def maximumGood(self, statements):
        n = len(statements)
        ans = 0

        def isValid(good):
            for i, g in enumerate(good):
                if not g:
                    continue
                for j in range(n):
                    if statements[i][j] == 2:
                        continue
                    if statements[i][j] != good[j]:
                        return bool(False)
            return bool(True)

        def dfs(good, i, count):
            nonlocal ans
            if i == n:
                if isValid(good):
                    ans = max(ans, count)
                return
            good.append(0)
            dfs(good, i + 1, count)
            good[-1] = 1
            dfs(good, i + 1, count + 1)
            good.pop()
        dfs([], 0, 0)
        return ans

class Solution:

    def minimumLines(self, points):
        n = len(points)
        allCovered = (1 << n) - 1
        maxLines = n // 2 + (n & 1)

        def getSlope(p, q):
            dx = p[0] - q[0]
            dy = p[1] - q[1]
            if dx == 0:
                return (0, p[0])
            if dy == 0:
                return (p[1], 0)
            d = gcd(dx, dy)
            x = dx // d
            y = dy // d
            return (x, y) if x > 0 else (-x, -y)

        @functools.lru_cache(None)
        def dfs(covered):
            if covered == allCovered:
                return 0
            ans = maxLines
            for i in range(n):
                if covered >> i & 1:
                    continue
                for j in range(n):
                    if i == j:
                        continue
                    newCovered = covered | 1 << i | 1 << j
                    slope = getSlope(points[i], points[j])
                    for k in range(n):
                        if getSlope(points[i], points[k]) == slope:
                            newCovered |= 1 << k
                    ans = min(ans, 1 + dfs(newCovered))
            return ans
        return dfs(0)

