class Bitset:

    def __init__(self, size):
        self.s = ['0'] * size
        self.r = ['1'] * size
        self.cnt = 0

    def fix(self, idx):
        if self.s[idx] == '0':
            self.cnt += 1
        self.s[idx] = '1'
        self.r[idx] = '0'

    def unfix(self, idx):
        if self.s[idx] == '1':
            self.cnt -= 1
        self.s[idx] = '0'
        self.r[idx] = '1'

    def flip(self):
        self.s, self.r = (self.r, self.s)
        self.cnt = len(self.s) - self.cnt

    def all(self):
        return bool(self.cnt == len(self.s))

    def one(self):
        return bool(self.cnt)

    def count(self):
        return self.cnt

    def toString(self):
        return ''.join(self.s)

