class Solution:

    def equalDigitFrequency(self, s):
        BASE = 11
        HASH = 1000000007
        counts = []
        count = collections.Counter()
        pows = [1]
        hash = [0]

        def val(c):
            return int(c) + 1
        for c in s:
            count[c] += 1
            counts.append(count.copy())
            pows.append(pows[-1] * BASE % HASH)
            hash.append((hash[-1] * BASE + val(c)) % HASH)

        def getRollingHash(l, r):
            """Returns the rolling hash of s[l..r)."""
            h = (hash[r] - hash[l] * pows[r - l]) % HASH
            return h + HASH if h < 0 else h
        return len({getRollingHash(i, j + 1) for i in range(len(s)) for j in range(i, len(s)) if self._isSameFreq(counts, i, j)})

    def _isSameFreq(self, counts, i, j):
        count = counts[j].copy()
        if i > 0:
            for c, freq in counts[i - 1].items():
                count[c] -= freq
                if count[c] == 0:
                    del count[c]
        return bool(min(count.values()) == max(count.values()))

