            freq = t.count[num]
            if freq > t.maxFreq:
                t.maxFreq = freq
                t.mx = num
            elif freq > t.secondMaxFreq:
                t.secondMaxFreq = freq
                t.secondMax = num
        if ts[0].mx == ts[1].mx:
            return len(nums) - max(ts[0].maxFreq + ts[1].secondMaxFreq, ts[1].maxFreq + ts[0].secondMaxFreq)
