class Solution:

    def removeOnes(self, grid):
        m = len(grid)
        n = len(grid[0])

        @functools.lru_cache(None)
        def dp(mask):
            """
      Returns the minimum number of operations to remove all 1s from the grid,
      where `mask` is the bitmask of the state of the grid.
      """
            if mask == 0:
                return 0
            ans = math.inf
            for i in range(m):
                for j in range(n):
                    if mask >> i * n + j & 1:
                        newMask = mask
                        for k in range(n):
                            newMask &= ~(1 << i * n + k)
                        for k in range(m):
                            newMask &= ~(1 << k * n + j)
                        ans = min(ans, 1 + dp(newMask))
            return ans
        return dp(self.encode(grid, m, n))

    def encode(self, grid, m, n):
        encoded = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j]:
                    encoded |= 1 << i * n + j
        return encoded

