class Solution:

    def buildWall(self, height, width, bricks):
        MOD = 1000000007
        rows = []
        self._buildRows(width, bricks, 0, rows)
        n = len(rows)
        dp = [1] * n
        graph = [[] for _ in range(n)]
        for i, a in enumerate(rows):
            for j, b in enumerate(rows):
                if not a & b:
                    graph[i].append(j)
        for _ in range(2, height + 1):
            newDp = [0] * n
            for i in range(n):
                for v in graph[i]:
                    newDp[i] += dp[v]
                    newDp[i] %= MOD
            dp = newDp
        return sum(dp) % MOD

    def _buildRows(self, width, bricks, path, rows):
        for brick in bricks:
            if brick == width:
                rows.append(path)
            elif brick < width:
                newWidth = width - brick
                self._buildRows(newWidth, bricks, path | 2 << newWidth, rows)

