class Solution:

    def singleDivisorTriplet(self, nums):
        ans = 0
        count = collections.Counter(nums)

        def divisible(summ, num):
            return summ % num == 0
        for a in range(1, 101):
            if count[a] == 0:
                continue
            for b in range(a, 101):
                if count[b] == 0:
                    continue
                for c in range(b, 101):
                    if count[c] == 0:
                        continue
                    summ = a + b + c
                    if divisible(summ, a) + divisible(summ, b) + divisible(summ, c) != 1:
                        continue
                    if a == b:
                        ans += count[a] * (count[a] - 1) // 2 * count[c]
                    elif b == c:
