            point = 0
            for i in range(12):
                if mask >> i & 1:
                    leftArrows -= aliceArrows[i] + 1
                    point += i
            return (leftArrows >= 0, point)
        for mask in range(FULL_MASK):
            shotable, point = getShotableAndPoint(mask, numArrows)
            if shotable and point > maxPoint:
                maxPoint = point
                maxMask = mask

        def getBobsArrows(mask, leftArrows):
            bobsArrows = [0] * 12
            for i in range(12):
                if mask >> i & 1:
                    bobsArrows[i] = aliceArrows[i] + 1
