            nonlocal ans
            if s == len(cookies):
                ans = min(ans, max(children))
                return
            for i in range(k):
                children[i] += cookies[s]
                dfs(s + 1, children)
                children[i] -= cookies[s]
        dfs(0, [0] * k)
        return ans

