    def checkContradictions(self, equations, values):
        strToInt = {}
        for u, v in equations:
            strToInt.setdefault(u, len(strToInt))
            strToInt.setdefault(v, len(strToInt))
        graph = [[] for _ in range(len(strToInt))]
        seen = [0.0] * len(graph)
        for i, ((A, B), value) in enumerate(zip(equations, values)):
            u = strToInt[A]
            v = strToInt[B]
            graph[u].append((v, value))
            graph[v].append((u, 1 / value))

        def dfs(u, val):
            if seen[u]:
                return bool(abs(val / seen[u] - 1) > 1e-05)
            seen[u] = val
            return bool(any((dfs(v, val / w) for v, w in graph[u])))
        for i in range(len(graph)):
            if not seen[i] and dfs(i, 1.0):
                return bool(True)
        return bool(False)

