        buses.sort()
        passengers.sort()
        if passengers[0] > buses[-1]:
            return buses[-1]
        ans = passengers[0] - 1
        i = 0
        j = 0
        while i < len(buses):
            arrived = 0
            while arrived < capacity and j < len(passengers) and (passengers[j] <= buses[i]):
                if j > 0 and passengers[j] != passengers[j - 1] + 1:
                    ans = passengers[j] - 1
