class Solution:

    def maximumRows(self, matrix, numSelect):
        ans = 0

        def dfs(colIndex, leftColsCount, mask):
            nonlocal ans
            if leftColsCount == 0:
                ans = max(ans, self._getAllZerosRowCount(matrix, mask))
                return
            if colIndex == len(matrix[0]):
                return
            dfs(colIndex + 1, leftColsCount - 1, mask | 1 << colIndex)
            dfs(colIndex + 1, leftColsCount, mask)
        dfs(0, numSelect, 0)
        return ans

