class Solution:

    def numberOfWays(self, startPos, endPos, k):
        val = k + endPos - startPos
        if val < 0 or val % 2 == 1:
            return 0
        rightStep = val // 2
        leftStep = k - rightStep
        if leftStep < 0:
            return 0
        return self._nCk(leftStep + rightStep, min(leftStep, rightStep))

    def _nCk(self, n, k):
        MOD = 1000000007
        dp = [1] + [0] * k
        for _ in range(n):
            for j in range(k, 0, -1):
                dp[j] += dp[j - 1]
                dp[j] %= MOD
        return dp[k]

