        n = len(price)
        dp = [[[0] * (maxCoupons + 1) for j in range(maxAmount + 1)] for i in range(n + 1)]
        for i in range(1, n + 1):
            currPrice = price[i - 1]
            currTastiness = tastiness[i - 1]
            for amount in range(maxAmount + 1):
                for coupon in range(maxCoupons + 1):
                    dp[i][amount][coupon] = dp[i - 1][amount][coupon]
                    if amount >= currPrice:
                        dp[i][amount][coupon] = max(dp[i][amount][coupon], dp[i - 1][amount - currPrice][coupon] + currTastiness)
                    if coupon > 0 and amount >= currPrice // 2:
                        dp[i][amount][coupon] = max(dp[i][amount][coupon], dp[i - 1][amount - currPrice // 2][coupon - 1] + currTastiness)
