        @lru_cache(None)
        def height(root):
            if not root:
                return 0
            return 1 + max(height(root.left), height(root.right))
        valToMaxHeight = {}

        def dfs(root, depth, maxHeight):
            if not root:
                return
            valToMaxHeight[root.val] = maxHeight
            dfs(root.left, depth + 1, max(maxHeight, depth + height(root.right)))
