class Solution:

    def mostProfitablePath(self, edges, bob, amount):
        n = len(amount)
        tree = [[] for _ in range(n)]
        parent = [0] * n
        aliceDist = [-1] * n
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        def dfs(u, prev, d):
            parent[u] = prev
            aliceDist[u] = d
            for v in tree[u]:
                if aliceDist[v] == -1:
                    dfs(v, u, d + 1)
        dfs(0, -1, 0)
        u = bob
        bobDist = 0
        while u != 0:
            if bobDist < aliceDist[u]:
                amount[u] = 0
            elif bobDist == aliceDist[u]:
                amount[u] //= 2
            u = parent[u]
            bobDist += 1
        return self._getMoney(tree, 0, -1, amount)

    def _getMoney(self, tree, u, prev, amount):
        if len(tree[u]) == 1 and tree[u][0] == prev:
            return amount[u]
        maxPath = -math.inf
        for v in tree[u]:
            if v != prev:
                maxPath = max(maxPath, self._getMoney(tree, v, u, amount))
        return amount[u] + maxPath

class Solution:

    def splitMessage(self, message, limit):
        MESSAGE_LENGTH = len(message)

        def sz(num):
            return len(str(num))
        b = 1
        aLength = sz(1)
        while b * limit < b * (sz(b) + 3) + aLength + MESSAGE_LENGTH:
            if sz(b) * 2 + 3 >= limit:
                return []
            b += 1
            aLength += sz(b)
        ans = []
        i = 0
        for a in range(1, b + 1):
            j = limit - (sz(a) + sz(b) + 3)
            ans.append(f'{message[i:i + j]}<{a}/{b}>')
            i += j
        return ans

