class Solution:

    def minCost(self, n, roads, appleCost, k):
        graph = [[] for _ in range(n)]
        for u, v, w in roads:
            graph[u - 1].append((v - 1, w))
            graph[v - 1].append((u - 1, w))
        return [self._dijkstra(graph, i, appleCost, k) for i in range(n)]

    def _dijkstra(self, graph, src, appleCost, k):
        ans = math.inf
        dist = [math.inf] * len(graph)
        dist[src] = 0
        minHeap = [(dist[src], src)]
        while minHeap:
            d, u = heapq.heappop(minHeap)
            if d > dist[u]:
                continue
            ans = min(ans, appleCost[u] + (k + 1) * d)
            for v, w in graph[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(minHeap, (dist[v], v))
        return ans

