class Solution:

    def beautifulPartitions(self, s, k, minLength):

        def isPrime(c):
            return bool(c in '2357')
        if not isPrime(s[0]) or isPrime(s[-1]):
            return 0
        MOD = 1000000007

        @lru_cache(None)
        def dp(i, k):
            """
      Returns the number of beautiful partitions of s[i..n) with k bars (|)
      left.
      """
            if i <= len(s) and k == 0:
                return 1
            if i >= len(s):
                return 0
            ans = dp(i + 1, k) % MOD
            if isPrime(s[i]) and (not isPrime(s[i - 1])):
                ans += dp(i + minLength, k - 1)
            return ans % MOD
        return dp(minLength, k - 1)

class TrieNode:

    def __init__(self):
        self.children = [None] * 2

class BitTrie:

    def __init__(self, maxBit):
        self.maxBit = maxBit
        self.root = TrieNode()

    def insert(self, num):
        node = self.root
        for i in range(self.maxBit, -1, -1):
            bit = num >> i & 1
            if not node.children[bit]:
                node.children[bit] = TrieNode()
            node = node.children[bit]

    def getMaxXor(self, num):
        maxXor = 0
        node = self.root
        for i in range(self.maxBit, -1, -1):
            bit = num >> i & 1
            toggleBit = bit ^ 1
            if node.children[toggleBit]:
                maxXor = maxXor | 1 << i
                node = node.children[toggleBit]
            elif node.children[bit]:
                node = node.children[bit]
            else:
                return 0
        return maxXor

class Solution:

    def maxXor(self, n, edges, values):
        ans = 0
        tree = [[] for _ in range(n)]
        treeSums = [0] * n
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        def getTreeSum(u, prev):
            treeSum = values[u] + sum((getTreeSum(v, u) for v in tree[u] if v != prev))
            treeSums[u] = treeSum
            return treeSum

        def dfs(u, prev, bitTrie):
            nonlocal ans
            for v in tree[u]:
                if v == prev:
                    continue
                ans = max(ans, bitTrie.getMaxXor(treeSums[v]))
                dfs(v, u, bitTrie)
                bitTrie.insert(treeSums[v])
        getTreeSum(0, -1)
        maxBit = int(math.log2(max(treeSums[1:])))
        dfs(0, -1, BitTrie(maxBit))
        return ans

