    def closestPrimes(self, left, right):
        isPrime = self._sieveEratosthenes(right + 1)
        primes = [i for i in range(left, right + 1) if isPrime[i]]
        if len(primes) < 2:
            return [-1, -1]
        minDiff = math.inf
        num1 = -1
        num2 = -1
        for a, b in zip(primes, primes[1:]):
            diff = b - a
            if diff < minDiff:
                minDiff = diff
                num1 = a
