        isPrime = [True] * n
        isPrime[0] = False
        isPrime[1] = False
        for i in range(2, int(n ** 0.5) + 1):
            if isPrime[i]:
                for j in range(i * i, n, i):
                    isPrime[j] = False
        return isPrime

class Solution:

    def maxFrequencyScore(self, nums, k):
        MOD = 1000000007
        count = collections.Counter(nums[:k])
        summ = self._getInitialSumm(count, MOD)
        ans = summ
        for i in range(k, len(nums)):
            leftNum = nums[i - k]
            summ = (summ - pow(leftNum, count[leftNum], MOD) + MOD) % MOD
            count[leftNum] -= 1
            if count[leftNum] > 0:
                summ = (summ + pow(leftNum, count[leftNum], MOD)) % MOD
            else:
                del count[leftNum]
            rightNum = nums[i]
            if count[rightNum] > 0:
                summ = (summ - pow(rightNum, count[rightNum], MOD) + MOD) % MOD
            count[rightNum] += 1
            summ = (summ + pow(rightNum, count[rightNum], MOD)) % MOD
            ans = max(ans, summ)
        return ans

    def _getInitialSumm(self, count, MOD):
        summ = 0
        for num, freq in count.items():
            summ = (summ + pow(num, freq, MOD)) % MOD
        return summ

