                appendZeros = i + zeroGroup
                if appendZeros <= maxLength:
                    dp[appendZeros] += dp[i]
                    dp[appendZeros] %= MOD
                appendOnes = i + oneGroup
                if appendOnes <= maxLength:
                    dp[appendOnes] += dp[i]
                    dp[appendOnes] %= MOD
