class Solution:

    def maxOutput(self, n, edges, price):
        ans = 0
        tree = [[] for _ in range(n)]
        maxSums = [0] * n
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        def maxSum(u, prev):
            maxChildSum = 0
            for v in tree[u]:
                if v != prev:
                    maxChildSum = max(maxChildSum, maxSum(v, u))
            maxSums[u] = price[u] + maxChildSum
            return maxSums[u]
        maxSum(0, -1)

        def reroot(u, prev, parentSum):
            nonlocal ans
            maxSubtreeSum1 = 0
            maxSubtreeSum2 = 0
            maxNode = -1
            for v in tree[u]:
                if v == prev:
                    continue
                if maxSums[v] > maxSubtreeSum1:
                    maxSubtreeSum2 = maxSubtreeSum1
                    maxSubtreeSum1 = maxSums[v]
                    maxNode = v
                elif maxSums[v] > maxSubtreeSum2:
                    maxSubtreeSum2 = maxSums[v]
            if len(tree[u]) == 1:
                ans = max(ans, parentSum, maxSubtreeSum1)
            for v in tree[u]:
                if v == prev:
                    continue
                nextParentSum = price[u] + max(parentSum, maxSubtreeSum2) if v == maxNode else price[u] + max(parentSum, maxSubtreeSum1)
                reroot(v, u, nextParentSum)
        reroot(0, -1, 0)
        return ans

class Solution:

    def countGoodSubsequences(self, s):
        MOD = 1000000007
        ans = 0
        count = collections.Counter(s)

        @functools.lru_cache(None)
        def fact(i):
            return 1 if i <= 1 else i * fact(i - 1) % MOD

        @functools.lru_cache(None)
        def inv(i):
            return pow(i, MOD - 2, MOD)

        @functools.lru_cache(None)
        def nCk(n, k):
            return fact(n) * inv(fact(k)) * inv(fact(n - k)) % MOD
        for freq in range(1, max(count.values()) + 1):
            numSubseqs = 1
            for charFreq in count.values():
                if charFreq >= freq:
                    numSubseqs = numSubseqs * (1 + nCk(charFreq, freq)) % MOD
            ans += numSubseqs - 1
            ans %= MOD
        return ans

