from dataclasses import dataclass

@dataclass(frozen=True)
class Task:
    taskDescription: str
    dueDate: int
    tags: list[str]

class TodoList:

    def __init__(self):
        self.taskId = 0
        self.taskIds = set()
        self.userIdToTaskIdToTasks = {}

    def addTask(self, userId, taskDescription, dueDate, tags):
        self.taskId += 1
        taskIdToTasks = self.userIdToTaskIdToTasks.setdefault(userId, {})
        taskIdToTasks[self.taskId] = Task(taskDescription, dueDate, tags)
        self.taskIds.add(self.taskId)
        return self.taskId

    def getAllTasks(self, userId):
        return [task.taskDescription for task in self._getTasksSortedByDueDate(userId)]

    def getTasksForTag(self, userId, tag):
        return [task.taskDescription for task in self._getTasksSortedByDueDate(userId) if tag in task.tags]

    def completeTask(self, userId, taskId):
        if taskId not in self.taskIds:
            return
        if userId not in self.userIdToTaskIdToTasks:
            return
        taskIdToTasks = self.userIdToTaskIdToTasks[userId]
        if taskId not in taskIdToTasks:
            return
        del taskIdToTasks[taskId]

    def _getTasksSortedByDueDate(self, userId):
        if userId not in self.userIdToTaskIdToTasks:
            return []
        taskIdToTasks = self.userIdToTaskIdToTasks[userId]
        return sorted([task for task in taskIdToTasks.values()], key=lambda x: x.dueDate)

class Solution:
    def run(self, operations, arguments):
        instance = TodoList(*arguments[0])
        answer = [None]
        for operation, args in zip(operations[1:], arguments[1:]):
            result = getattr(instance, operation)(*args)
            answer.append(result)
        return answer

