        i = 0
        j = 0

        def nextGrid(i, j, target):
            """
      Returns (x, y), where grid[x][y] == target if (i, j) can reach target.
      """
            for dx, dy in DIRS:
                x = i + dx
                y = j + dy
                if x < 0 or x >= n or y < 0 or (y >= n):
                    continue
                if grid[x][y] == target:
                    return (x, y)
            return (-1, -1)
        for target in range(1, n * n):
            x, y = nextGrid(i, j, target)
            if x == -1 and y == -1:
                return bool(False)
            i = x
            j = y
        return bool(True)

class Solution:

    def beautifulSubsets(self, nums, k):
        count = collections.Counter(nums)
        modToSubset = collections.defaultdict(set)
        for num in nums:
            modToSubset[num % k].add(num)
        prevNum = -k
        skip = 0
        pick = 0
        for subset in modToSubset.values():
            for num in sorted(subset):
                nonEmptyCount = 2 ** count[num] - 1
                skip, pick = (skip + pick, nonEmptyCount * (1 + skip + (0 if num - prevNum == k else pick)))
                prevNum = num
        return skip + pick

