class Solution:

    def primeSubOperation(self, nums):
        MAX = 1000
        primes = self._sieveEratosthenes(MAX)
        prevNum = 0
        for num in nums:
            i = bisect_left(primes, num - prevNum)
            if i > 0:
                num -= primes[i - 1]
            if num <= prevNum:
                return bool(False)
            prevNum = num
        return bool(True)

    def _sieveEratosthenes(self, n):
        isPrime = [True] * n
        isPrime[0] = False
        isPrime[1] = False
        for i in range(2, int(n ** 0.5) + 1):
            if isPrime[i]:
                for j in range(i * i, n, i):
                    isPrime[j] = False
        return [i for i in range(n) if isPrime[i]]

class Solution:

    def minimumTime(self, hens, grains):
        hens.sort()
        grains.sort()

        def canEat(time):
            """Returns True if `hens` can eat all `grains` within `time`."""
            i = 0
            for hen in hens:
                rightMoves = time
                if grains[i] < hen:
                    leftMoves = hen - grains[i]
                    if leftMoves > time:
                        return bool(False)
                    leftThenRight = time - 2 * leftMoves
                    rightThenLeft = (time - leftMoves) // 2
                    rightMoves = max(0, leftThenRight, rightThenLeft)
                i = bisect_right(grains, hen + rightMoves)
                if i == len(grains):
                    return bool(True)
            return bool(False)
        maxMoves = int(1.5 * (max(hens + grains) - min(hens + grains)))
        return bisect_left(range(maxMoves), True, key=canEat)

