class Solution:

    def beautifulPair(self, nums1, nums2):

        def dist(x1, y1, x2, y2):
            return abs(x1 - x2) + abs(y1 - y2)

        def dfs(l, r):
            if l >= r:
                return (inf, -1, -1)
            m = l + r >> 1
            x = points[m][0]
            d1, pi1, pj1 = dfs(l, m)
            d2, pi2, pj2 = dfs(m + 1, r)
            if d1 > d2 or (d1 == d2 and (pi1 > pi2 or (pi1 == pi2 and pj1 > pj2))):
                d1, pi1, pj1 = (d2, pi2, pj2)
            t = [p for p in points[l:r + 1] if abs(p[0] - x) <= d1]
            t.sort(key=lambda x: x[1])
            for i in range(len(t)):
                for j in range(i + 1, len(t)):
                    if t[j][1] - t[i][1] > d1:
                        break
                    pi, pj = sorted([t[i][2], t[j][2]])
                    d = dist(t[i][0], t[i][1], t[j][0], t[j][1])
                    if d < d1 or (d == d1 and (pi < pi1 or (pi == pi1 and pj < pj1))):
                        d1, pi1, pj1 = (d, pi, pj)
            return (d1, pi1, pj1)
        pl = defaultdict(list)
        for i, (x, y) in enumerate(zip(nums1, nums2)):
            pl[x, y].append(i)
        points = []
        for i, (x, y) in enumerate(zip(nums1, nums2)):
            if len(pl[x, y]) > 1:
                return [i, pl[x, y][1]]
            points.append((x, y, i))
        points.sort()
        _, pi, pj = dfs(0, len(points) - 1)
        return [pi, pj]

class Solution:

    def diagonalPrime(self, nums):

        def isPrime(n):
            if n <= 1:
                return bool(False)
            for i in range(2, int(n ** 0.5) + 1):
                if n % i == 0:
                    return bool(False)
            return bool(True)
        primes1 = [row[i] for i, row in enumerate(nums) if isPrime(row[i])]
        primes2 = [row[-1 - i] for i, row in enumerate(nums) if isPrime(row[-1 - i])]
        return max(max(primes1) if primes1 else 0, max(primes2) if primes2 else 0)

class Solution:

    def distance(self, nums):
        ans = [0] * len(nums)
        numToIndices = collections.defaultdict(list)
        for i, num in enumerate(nums):
            numToIndices[num].append(i)
        for indices in numToIndices.values():
            n = len(indices)
            if n == 1:
                continue
            sumSoFar = sum(indices)
            prevIndex = 0
            for i in range(n):
                sumSoFar += (i - 1) * (indices[i] - prevIndex)
                sumSoFar -= (n - 1 - i) * (indices[i] - prevIndex)
                ans[indices[i]] = sumSoFar
                prevIndex = indices[i]
        return ans

class Solution:

    def minimizeMax(self, nums, p):
        nums.sort()

        def numPairs(maxDiff):
            """
      Returns the number of pairs that can be obtained if the difference between
      each pair <= `maxDiff`.
      """
            pairs = 0
            i = 1
            while i < len(nums):
                if nums[i] - nums[i - 1] <= maxDiff:
                    pairs += 1
                    i += 2
                else:
                    i += 1
            return pairs
        return bisect_left(range(nums[-1] - nums[0]), p, key=numPairs)

