class Solution:

    def minimumCost(self, start, target, specialRoads):
        return self.dijkstra(specialRoads, *start, *target)

    def dijkstra(self, specialRoads, srcX, srcY, dstX, dstY):
        n = len(specialRoads)
        dist = [math.inf] * n
        minHeap = []
        for u, (x1, y1, _, _, cost) in enumerate(specialRoads):
            d = abs(x1 - srcX) + abs(y1 - srcY) + cost
            dist[u] = d
            heapq.heappush(minHeap, (dist[u], u))
        while minHeap:
            d, u = heapq.heappop(minHeap)
            if d > dist[u]:
                continue
            _, _, ux2, uy2, _ = specialRoads[u]
            for v in range(n):
                if v == u:
                    continue
                vx1, vy1, _, _, vcost = specialRoads[v]
                newDist = d + abs(vx1 - ux2) + abs(vy1 - uy2) + vcost
                if newDist < dist[v]:
                    dist[v] = newDist
                    heapq.heappush(minHeap, (dist[v], v))
        ans = abs(dstX - srcX) + abs(dstY - srcY)
        for u in range(n):
            _, _, x2, y2, _ = specialRoads[u]
            ans = min(ans, dist[u] + abs(dstX - x2) + abs(dstY - y2))
        return ans

class Solution:

    def smallestBeautifulString(self, s, k):
        chars = list(s)
        for i in reversed(range(len(chars))):
            chars[i] = chr(ord(chars[i]) + 1)
            while self._containsPalindrome(chars, i):
                chars[i] = chr(ord(chars[i]) + 1)
            if chars[i] < chr(ord('a') + k):
                return self._changeSuffix(chars, i + 1)
        return ''

    def _containsPalindrome(self, chars, i):
        """Returns True if chars[0..i] contains palindrome."""
        return bool(i > 0 and chars[i] == chars[i - 1] or (i > 1 and chars[i] == chars[i - 2]))

    def _changeSuffix(self, chars, i):
        """
    Returns a string, where replacing sb[i..n) with the smallest possible
    letters don't form any palindrome substring.
    """
        for j in range(i, len(chars)):
            chars[j] = 'a'
            while self._containsPalindrome(chars, j):
                chars[j] = chr(ord(chars[j]) + 1)
        return ''.join(chars)

class Solution:

    def tourOfKnight(self, m, n, r, c):
        DIRS = ((1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2))
        ans = [[-1] * n for _ in range(m)]

        def dfs(i, j, step):
            if step == m * n:
                return bool(True)
            if i < 0 or i >= m or j < 0 or (j >= n):
                return bool(False)
            if ans[i][j] != -1:
                return bool(False)
            ans[i][j] = step
            for dx, dy in DIRS:
                if dfs(i + dx, j + dy, step + 1):
                    return bool(True)
            ans[i][j] = -1
            return bool(False)
        dfs(r, c, 0)
        return ans

