        distinctSuffix = 0
        for num in nums:
            if suffixCount[num] == 0:
                distinctSuffix += 1
            suffixCount[num] += 1
        for num in nums:
            if prefixCount[num] == 0:
                distinctPrefix += 1
            prefixCount[num] += 1
            if suffixCount[num] == 1:
                distinctSuffix -= 1
            suffixCount[num] -= 1
            ans.append(distinctPrefix - distinctSuffix)
        return ans

class FrequencyTracker:

    def __init__(self):
        self.count = collections.Counter()
        self.freqCount = collections.Counter()

    def add(self, number):
        if self.count[number] > 0:
            self.freqCount[self.count[number]] -= 1
        self.count[number] += 1
        self.freqCount[self.count[number]] += 1

    def deleteOne(self, number):
        if self.count[number] == 0:
            return
        self.freqCount[self.count[number]] -= 1
        self.count[number] -= 1
        self.freqCount[self.count[number]] += 1

    def hasFrequency(self, frequency):
        return bool(self.freqCount[frequency] > 0)

