        suffix = [0] * n
        for i in range(1, n):
            prefix[i] = prefix[i - 1] | nums[i - 1]
        for i in range(n - 2, -1, -1):
            suffix[i] = suffix[i + 1] | nums[i + 1]
        return max((p | num << k | s for num, p, s in zip(nums, prefix, suffix)))

