    def maxStrength(self, nums):
        posProd = 1
        negProd = 1
        maxNeg = -math.inf
        negCount = 0
        hasPos = False
        hasZero = False
        for num in nums:
            if num > 0:
                posProd *= num
                hasPos = True
            elif num < 0:
                negProd *= num
                maxNeg = max(maxNeg, num)
                negCount += 1
            else:
                hasZero = True
        if negCount == 0 and (not hasPos):
            return 0
        if negCount % 2 == 0:
            return negProd * posProd
        if negCount >= 3:
            return negProd // maxNeg * posProd
        if hasPos:
            return posProd
        if hasZero:
            return 0
        return maxNeg

class UnionFind:

    def __init__(self, n):
        self.id = list(range(n))
        self.sz = [1] * n

    def unionBySize(self, u, v):
        i = self._find(u)
        j = self._find(v)
        if i == j:
            return
        if self.sz[i] < self.sz[j]:
            self.sz[j] += self.sz[i]
            self.id[i] = j
        else:
            self.sz[i] += self.sz[j]
            self.id[j] = i

    def getSize(self, i):
        return self.sz[i]

    def _find(self, u):
        if self.id[u] != u:
            self.id[u] = self._find(self.id[u])
        return self.id[u]

class Solution:

    def canTraverseAllPairs(self, nums):
        n = len(nums)
        mx = max(nums)
        maxPrimeFactor = self._sieveEratosthenes(mx + 1)
        primeToFirstIndex = collections.defaultdict(int)
        uf = UnionFind(n)
        for i, num in enumerate(nums):
            for prime_factor in self._getPrimeFactors(num, maxPrimeFactor):
                if prime_factor in primeToFirstIndex:
                    uf.unionBySize(primeToFirstIndex[prime_factor], i)
                else:
                    primeToFirstIndex[prime_factor] = i
        return bool(any((uf.getSize(i) == n for i in range(n))))

    def _sieveEratosthenes(self, n):
        """Gets the minimum prime factor of i, where 1 < i <= n."""
        minPrimeFactors = [i for i in range(n + 1)]
        for i in range(2, int(n ** 0.5) + 1):
            if minPrimeFactors[i] == i:
                for j in range(i * i, n, i):
                    minPrimeFactors[j] = min(minPrimeFactors[j], i)
        return minPrimeFactors

    def _getPrimeFactors(self, num, minPrimeFactors):
        primeFactors = []
        while num > 1:
            divisor = minPrimeFactors[num]
            primeFactors.append(divisor)
            while num % divisor == 0:
                num //= divisor
        return primeFactors

