class Solution:

    def shortestPathWithHops(self, n, edges, s, d, k):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        return self._dijkstra(graph, s, d, k)

    def _dijkstra(self, graph, src, dst, k):
        dist = [[math.inf for _ in range(k + 1)] for _ in range(len(graph))]
        dist[src][k] = 0
        minHeap = [(dist[src][k], src, k)]
        while minHeap:
            d, u, hops = heapq.heappop(minHeap)
            if u == dst:
                return d
            if dist[u][hops] > d:
                continue
            for v, w in graph[u]:
                if d + w < dist[v][hops]:
                    dist[v][hops] = d + w
                    heapq.heappush(minHeap, (dist[v][hops], v, hops))
                if hops > 0 and d < dist[v][hops - 1]:
                    dist[v][hops - 1] = d
                    heapq.heappush(minHeap, (dist[v][hops - 1], v, hops - 1))

