        ans = [0] * len(queries)
        count = [0] * (n + 1)
        logs.sort(key=lambda x: x[1])
        i = 0
        j = 0
        servers = 0
        for queryIndex, query in sorted([IndexedQuery(i, query) for i, query in enumerate(queries)], key=lambda x: x.query):
            while j < len(logs) and logs[j][1] <= query:
                count[logs[j][0]] += 1
                if count[logs[j][0]] == 1:
                    servers += 1
                j += 1
            while i < len(logs) and logs[i][1] < query - x:
