            for i in range(len(a)):
                aSuffix = a[i:]
                bPrefix = b[:len(aSuffix)]
                if aSuffix == bPrefix:
                    return a + b[len(bPrefix):]
            return a + b
        abc = merge(a, merge(b, c))
        acb = merge(a, merge(c, b))
        bac = merge(b, merge(a, c))
        bca = merge(b, merge(c, a))
        cab = merge(c, merge(a, b))
        cba = merge(c, merge(b, a))
        return self._getMin([abc, acb, bac, bca, cab, cba])

    def _getMin(self, words):
        """Returns the lexicographically smallest string."""

        def getMin(a, b):
            """Returns the lexicographically smaller string."""
            return a if len(a) < len(b) or (len(a) == len(b) and a < b) else b
        res = words[0]
        for i in range(1, len(words)):
            res = getMin(res, words[i])
        return res

class Solution:

    def countSteppingNumbers(self, low, high):
        MOD = 1000000007
        low = '0' * (len(high) - len(low)) + low

        @functools.lru_cache(None)
        def dp(i, prevDigit, isLeadingZero, tight1, tight2):
            """
      Returns the number of valid integers, considering the i-th digit, where
      `prevDigit` is the previous digit, `tight1` indicates if the current
      digit is tightly bound for `low`, and `tight2` indicates if the current
      digit is tightly bound for `high`.
      """
            if i == len(high):
                return 1
            res = 0
            minDigit = int(low[i]) if tight1 else 0
            maxDigit = int(high[i]) if tight2 else 9
            for d in range(minDigit, maxDigit + 1):
                nextTight1 = tight1 and d == minDigit
                nextTight2 = tight2 and d == maxDigit
                if isLeadingZero:
                    res += dp(i + 1, d, isLeadingZero and d == 0, nextTight1, nextTight2)
                elif abs(d - prevDigit) == 1:
                    res += dp(i + 1, d, False, nextTight1, nextTight2)
                res %= MOD
            return res
        return dp(0, -1, True, True, True)

