        sum2 = sum(nums2)
        for i, (num2, num1) in enumerate(sorted(zip(nums2, nums1)), 1):
            for j in range(1, i + 1):
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + num2 * j + num1)
