    def findMaximumElegance(self, items, k):
        ans = 0
        totalProfit = 0
        seenCategories = set()
        decreasingDuplicateProfits = []
        items.sort(reverse=True)
        for i in range(k):
            profit, category = items[i]
            totalProfit += profit
            if category in seenCategories:
                decreasingDuplicateProfits.append(profit)
            else:
                seenCategories.add(category)
        ans = totalProfit + len(seenCategories) ** 2
        for i in range(k, len(items)):
            profit, category = items[i]
            if category not in seenCategories and decreasingDuplicateProfits:
                totalProfit -= decreasingDuplicateProfits.pop()
                totalProfit += profit
                seenCategories.add(category)
                ans = max(ans, totalProfit + len(seenCategories) ** 2)
        return ans

class Solution:

    def minimumSeconds(self, land):
        self.DIRS = ((0, 1), (1, 0), (0, -1), (-1, 0))
        m = len(land)
        n = len(land[0])
        floodDist = self._getFloodDist(land)
        startPos = self._getStartPos(land, 'S')
        q = collections.deque([startPos])
        seen = {startPos}
        step = 1
        while q:
            for _ in range(len(q)):
                i, j = q.popleft()
                for dx, dy in self.DIRS:
                    x = i + dx
                    y = j + dy
                    if x < 0 or x == m or y < 0 or (y == n):
                        continue
                    if land[x][y] == 'D':
                        return step
                    if floodDist[x][y] <= step or land[x][y] == 'X' or (x, y) in seen:
                        continue
                    q.append((x, y))
                    seen.add((x, y))
            step += 1
        return -1

    def _getFloodDist(self, land):
        m = len(land)
        n = len(land[0])
        dist = [[math.inf] * n for _ in range(m)]
        q = collections.deque()
        seen = set()
        for i, row in enumerate(land):
            for j, cell in enumerate(row):
                if cell == '*':
                    q.append((i, j))
                    seen.add((i, j))
        d = 0
        while q:
            for _ in range(len(q)):
                i, j = q.popleft()
                dist[i][j] = d
                for dx, dy in self.DIRS:
                    x = i + dx
                    y = j + dy
                    if x < 0 or x == m or y < 0 or (y == n):
                        continue
                    if land[x][y] in 'XD' or (x, y) in seen:
                        continue
                    q.append((x, y))
                    seen.add((x, y))
            d += 1
        return dist

    def _getStartPos(self, land, c):
        for i, row in enumerate(land):
            for j, cell in enumerate(row):
                if cell == c:
                    return (i, j)

