        NO_MISSING_BIT = 31
        maxBit = 31
        ans = 0
        minMissingBit = NO_MISSING_BIT
        count = collections.Counter((int(math.log2(num)) for num in nums))
        for bit in range(maxBit):
            if target >> bit & 1:
                if count[bit] > 0:
                    count[bit] -= 1
                else:
                    minMissingBit = min(minMissingBit, bit)
            if minMissingBit != NO_MISSING_BIT and count[bit] > 0:
