        diffIndices = [i for i, (a, b) in enumerate(zip(s1, s2)) if a != b]
        if not diffIndices:
            return 0
        if len(diffIndices) & 1:
            return -1

        @functools.lru_cache(None)
        def dp(i):
            """Returns the minimum cost to correct diffIndices[i..n)."""
            if i == len(diffIndices):
