        count = collections.Counter(nums)
        minFreq = min(count.values())
        for groupSize in range(minFreq, 0, -1):
            numGroups = self.getNumGroups(count, groupSize)
            if numGroups > 0:
                return numGroups
        raise ValueError('Invalid argument')

    def getNumGroups(self, count, groupSize):
        """Returns the number of groups if each group's size is `groupSize` or `groupSize + 1`."""
        numGroups = 0
        for freq in count.values():
            a = freq // (groupSize + 1)
            b = freq % (groupSize + 1)
            if b == 0:
                numGroups += a
            elif groupSize - b <= a:
                numGroups += a + 1
            else:
                return 0
        return numGroups

