class FenwickTree:

    def __init__(self, n):
        self.vals = [0] * (n + 1)

    def maximize(self, i, val):
        while i < len(self.vals):
            self.vals[i] = max(self.vals[i], val)
            i += FenwickTree.lowbit(i)

    def get(self, i):
        res = 0
        while i > 0:
            res = max(res, self.vals[i])
            i -= FenwickTree.lowbit(i)
        return res

    @staticmethod
    def lowbit(i):
        return i & -i

