class Solution:

    def distributeCandies(self, n, limit):

        def ways(n):
            """Returns the number of ways to distribute n candies to 3 children."""
            if n < 0:
                return 0
            return math.comb(n + 2, 2)
        limitPlusOne = limit + 1
        oneChildExceedsLimit = ways(n - limitPlusOne)
