class TrieNode:

    def __init__(self):
        self.children = [None] * 2
        self.mn = math.inf
        self.mx = -math.inf

class BitTrie:

    def __init__(self, maxBit):
        self.maxBit = maxBit
        self.root = TrieNode()

    def insert(self, num):
        node = self.root
        for i in range(self.maxBit, -1, -1):
            bit = num >> i & 1
            if not node.children[bit]:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.mn = min(node.mn, num)
            node.mx = max(node.mx, num)

    def getMaxXor(self, x):
        """Returns max(x ^ y) where |x - y| <= min(x, y).

    If x <= y, |x - y| <= min(x, y) can be written as y - x <= x.
    So, y <= 2 * x.
    """
        maxXor = 0
        node = self.root
        for i in range(self.maxBit, -1, -1):
            bit = x >> i & 1
            toggleBit = bit ^ 1
            if node.children[toggleBit] and node.children[toggleBit].mx > x and (node.children[toggleBit].mn <= 2 * x):
                maxXor = maxXor | 1 << i
                node = node.children[toggleBit]
            elif node.children[bit]:
                node = node.children[bit]
            else:
                return 0
        return maxXor

