    def _countCompleteStrings(self, word, k, windowSize):
        """
    Returns the number of complete substrings of `windowSize` of `word`.
    """
        res = 0
        countLetters = 0
        count = collections.Counter()
        for i, c in enumerate(word):
            count[c] += 1
            countLetters += 1
            if i > 0 and abs(ord(c) - ord(word[i - 1])) > 2:
