            tree[v].append(u)

        def dfs(u, prev):
            res = ChildCost(cost[u])
            for v in tree[u]:
                if v != prev:
                    res.update(dfs(v, u))
            ans[u] = res.maxProduct()
            return res
        dfs(0, -1)
        return ans

