            for i in range(1, n + 1):
                if used >> i & 1 == 0 and (num % i == 0 or i % num == 0):
                    count += dfs(num + 1, used | 1 << i)
            return count
        return dfs(1, 0)

class Solution:

    def minOperations(self, nums, k):
        return functools.reduce(operator.xor, nums, k).bit_count()

class Solution:

    def minimumOperationsToMakeEqual(self, x, y):
        if x <= y:
            return y - x
        queue = collections.deque([x])
        seen = set()
        ans = 0
        while queue:
            for _ in range(len(queue)):
                num = queue.popleft()
                if num == y:
                    return ans
                if num in seen:
                    continue
                seen.add(num)
                if num % 11 == 0:
                    queue.append(num // 11)
                if num % 5 == 0:
                    queue.append(num // 5)
                queue.append(num - 1)
                queue.append(num + 1)
            ans += 1

class Solution:

    def numberOfPowerfulInt(self, start, finish, limit, s):

        @cache
        def dfs(pos, lim):
            if len(t) < n:
                return 0
            if len(t) - pos == n:
                return int(s <= t[pos:]) if lim else 1
            up = min(int(t[pos]) if lim else 9, limit)
            ans = 0
            for i in range(up + 1):
                ans += dfs(pos + 1, lim and i == int(t[pos]))
            return ans
        n = len(s)
        t = str(start - 1)
        a = dfs(0, True)
        dfs.cache_clear()
        t = str(finish)
        b = dfs(0, True)
        return b - a

class Solution:

    def areaOfMaxDiagonal(self, dimensions):
        a, b = max(dimensions, key=lambda x: (x[0] ** 2 + x[1] ** 2, x[0] * x[1]))
        return a * b
